#!/usr/bin/env bash
# Canvas persistence smoke test: projects, canvases, optimistic locking, state validation, authorization.
# Needs a running stack (pnpm dev, or pnpm docker:up, after pnpm db:migrate), curl, jq and pnpm (Node 22).
# States are generated by packages/canvas-doc/scripts/make-state.ts.
#   WEB_URL=http://localhost:3000 GATEWAY_URL=http://localhost:4000 scripts/smoke-p1.sh
set -u

WEB_URL="${WEB_URL:-http://localhost:3000}"
GATEWAY_URL="${GATEWAY_URL:-http://localhost:4000}"
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
JAR_A="$(mktemp)"
JAR_B="$(mktemp)"
BODY="$(mktemp)"
trap 'rm -f "$JAR_A" "$JAR_B" "$BODY"' EXIT
failures=0

check() { # check <name> <expected> <actual>
  if [ "$2" = "$3" ]; then echo "PASS  $1 ($3)"; else echo "FAIL  $1: expected $2, got $3"; failures=$((failures + 1)); fi
}
signup_token() { # signup_token <jar> -> prints "<user id> <token>"
  local email="smoke-$(date +%s)-$RANDOM@example.com" signup token
  signup=$(curl -s -c "$1" -X POST "$WEB_URL/api/auth/sign-up/email" \
    -H 'content-type: application/json' -H "origin: $WEB_URL" \
    -d "{\"name\":\"smoke\",\"email\":\"$email\",\"password\":\"password-1234\"}")
  token=$(curl -s -b "$1" "$WEB_URL/api/auth/token" | jq -r .token)
  echo "$(echo "$signup" | jq -r .user.id) $token"
}
make_state() { (cd "$ROOT" && pnpm --silent --filter @creative/canvas-doc make-state "$1"); }
# api <token> <method> <path> [json body file] -> prints the status; the response body goes to $BODY
api() {
  local token="$1" method="$2" path="$3" data="${4:-}"
  if [ -n "$data" ]; then
    curl -s -o "$BODY" -w "%{http_code}" -X "$method" "$GATEWAY_URL$path" \
      -H "authorization: Bearer $token" -H 'content-type: application/json' --data-binary "@$data"
  else
    curl -s -o "$BODY" -w "%{http_code}" -X "$method" "$GATEWAY_URL$path" -H "authorization: Bearer $token"
  fi
}
put_body() { # put_body <baseVersion> <state> -> path of a temp JSON file
  local file; file="$(mktemp)"
  jq -n --argjson v "$1" --arg s "$2" '{baseVersion: $v, state: $s}' > "$file"
  echo "$file"
}
save() { # save <token> <path> <baseVersion> <state> -> status
  local file code; file="$(put_body "$3" "$4")"
  code=$(api "$1" PUT "$2/state" "$file")
  rm -f "$file"
  echo "$code"
}

echo "== P1: projects, canvases and authorization"
check "P1.1 GET /api/v1/projects without a token" 401 \
  "$(curl -s -o /dev/null -w '%{http_code}' "$GATEWAY_URL/api/v1/projects")"
read -r USER_A TOKEN_A < <(signup_token "$JAR_A")
read -r USER_B TOKEN_B < <(signup_token "$JAR_B")
check "P1.2 two distinct users signed up" true "$([ -n "$USER_A" ] && [ "$USER_A" != "$USER_B" ] && echo true || echo false)"

tmp="$(mktemp)"; echo '{"name":"Smoke project"}' > "$tmp"
check "P1.3 A creates a project" 201 "$(api "$TOKEN_A" POST /api/v1/projects "$tmp")"
rm -f "$tmp"
PROJECT=$(jq -r .project.id "$BODY")
CANVAS=$(jq -r '.project.canvases[0].id' "$BODY")
CPATH="/api/v1/projects/$PROJECT/canvases/$CANVAS"

check "P1.4 GET canvas" 200 "$(api "$TOKEN_A" GET "$CPATH")"
check "P1.5 new canvas is version 0" 0 "$(jq -r .canvas.version "$BODY")"

echo "== save, conflict, validation"
VALID=$(make_state valid)
check "P1.6 PUT valid state at baseVersion 0" 200 "$(save "$TOKEN_A" "$CPATH" 0 "$VALID")"
check "P1.7 version is now 1" 1 "$(jq -r .version "$BODY")"
check "P1.8 PUT again at baseVersion 0 (stale)" 409 "$(save "$TOKEN_A" "$CPATH" 0 "$VALID")"
check "P1.9 conflict reports currentVersion" 1 "$(jq -r .currentVersion "$BODY")"
for kind in dangling-edge unknown-node bad-config future-schema; do
  check "P1.10 PUT $kind state is rejected" 422 "$(save "$TOKEN_A" "$CPATH" 1 "$(make_state "$kind")")"
done
check "P1.11 PUT undecodable bytes is rejected" 422 "$(save "$TOKEN_A" "$CPATH" 1 "AQIDBAUG")"
check "P1.12 GET after rejected saves still shows version 1" 1 "$(api "$TOKEN_A" GET "$CPATH" >/dev/null; jq -r .canvas.version "$BODY")"
check "P1.13 PUT malformed base64 is a 400" 400 "$(save "$TOKEN_A" "$CPATH" 1 "not base64!")"

echo "== snapshot"
check "P1.14 GET snapshot" 200 "$(api "$TOKEN_A" GET "$CPATH/snapshot")"
check "P1.15 snapshot has no run-time status or viewport" 0 "$(grep -cE '"status"|"viewport"' "$BODY")"
check "P1.16 snapshot has the saved nodes" 2 "$(jq -r '.snapshot.nodes | length' "$BODY")"

echo "== large state through the gateway and the web rewrite (about 800 KB of base64)"
LARGE=$(make_state large)
check "P1.17 PUT large state via the gateway" 200 "$(save "$TOKEN_A" "$CPATH" 1 "$LARGE")"
file="$(put_body 2 "$LARGE")"
check "P1.18 PUT large state via the web origin rewrite" 200 \
  "$(curl -s -o "$BODY" -w '%{http_code}' -X PUT "$WEB_URL/gateway$CPATH/state" -H "authorization: Bearer $TOKEN_A" -H 'content-type: application/json' --data-binary "@$file")"
rm -f "$file"

echo "== another user sees 404 everywhere"
check "P1.19 B GET A's canvas" 404 "$(api "$TOKEN_B" GET "$CPATH")"
check "P1.20 B GET A's snapshot" 404 "$(api "$TOKEN_B" GET "$CPATH/snapshot")"
check "P1.21 B PUT A's canvas" 404 "$(save "$TOKEN_B" "$CPATH" 3 "$VALID")"
check "P1.22 B lists no project of A" 0 \
  "$(api "$TOKEN_B" GET /api/v1/projects >/dev/null; jq --arg p "$PROJECT" '[.projects[] | select(.id == $p)] | length' "$BODY")"
check "P1.23 A lists the project" 1 \
  "$(api "$TOKEN_A" GET /api/v1/projects >/dev/null; jq --arg p "$PROJECT" '[.projects[] | select(.id == $p)] | length' "$BODY")"
check "P1.24 non-uuid ids are a 400" 400 "$(api "$TOKEN_A" GET /api/v1/projects/x/canvases/y)"

if [ "$failures" -gt 0 ]; then echo "$failures check(s) failed"; exit 1; fi
echo "all checks passed"
